def test_evalString() -> None:
    # Every single-byte character should round-trip through repr().
    for i in range(256):
        c = chr(i)
        assert evalString(repr(c)) == c

    cases = {
        r"'hello\nworld'": "hello\nworld",
        r"'tab:\t'": "tab:\t",
        r"'quote:\''": "quote:'",
        r'"quote:\""': 'quote:"',
        r"'backslash:\\'": "backslash:\\",
        r"'\x41\x42'": "AB",
        r"'\101\102'": "AB",
        "'''multiple\nlines'''": "multiple\nlines",
        r"'\q'": r"\q",  # Unknown escapes are preserved.
    }

    for literal, expected in cases.items():
        assert evalString(literal) == expected

    for invalid in (r"'\x'", r"'\xG1'"):
        try:
            evalString(invalid)
        except ValueError:
            pass
        else:
            raise AssertionError(f"Expected ValueError for {invalid!r}")

